const followers = (v: string) => {
  const { source, target } = follows.specification.E
  const names = Object.keys(target)
    .filter((e) => target[e] === v)
    .map((e) => source[e])
  return names.length === 0 ? 'no one' : names.join(', ')
}

preview.append(view.col(view.title('Followers, picked in the plot'), solidView(Picker)))
